/** Core metrics: cost · accuracy · latency (docs/00 §8), from the accepted evaluation run.
 *  The data is generated by tools/render_results.py from evals/results (never typed by hand);
 *  a value that was not measured shows as —, never as met. */

export type CoreMetricsData = {
  run_id: string | null;
  gate: string;
  tiers: {
    tier: string;
    models: string[];
    accuracy_gates: Record<string, string>;
    accuracy_pass: boolean;
    cost_per_answer_usd: number | null;
    call_latency_p50_s: number | null;
    call_latency_p95_s: number | null;
  }[];
  answers: {
    type: string;
    label: string;
    answers: number | null;
    cost_mean_usd: number | null;
    cost_p95_usd: number | null;
    latency_p50_s: number | null;
    latency_p95_s: number | null;
  }[];
  targets: { id: string; label: string; value: number | null; target: string; met: boolean | null }[];
};

const usd = (v: number | null) => (v === null ? "—" : `$${v.toFixed(4)}`);
const sec = (v: number | null) => (v === null ? "—" : `${v.toFixed(1)} s`);
const mark = (status: string) => (status === "pass" ? "passes" : status === "fail" ? "fails" : "not run");

export function CoreMetrics({ data }: { data: CoreMetricsData }) {
  return (
    <section aria-labelledby="core-heading">
      <h2 id="core-heading" className="kicker">
        Core metrics: cost · accuracy · latency
      </h2>
      <p className="note">
        From evaluation run {data.run_id ?? "—"}. Latency comes from recorded live model calls. Cost and latency
        checks: {mark(data.gate)}.
      </p>
      <table className="data">
        <caption className="sr-only">Models by tier</caption>
        <thead>
          <tr>
            <th scope="col">Tier</th>
            <th scope="col">Model</th>
            <th scope="col">Accuracy checks</th>
            <th scope="col">Cost per answer</th>
            <th scope="col">Call latency p50 / p95</th>
          </tr>
        </thead>
        <tbody>
          {data.tiers.map((t) => (
            <tr key={t.tier}>
              <td className="lead">{t.tier}</td>
              <td data-label="Model">{t.models.join(", ") || "—"}</td>
              <td data-label="Accuracy checks">
                {Object.entries(t.accuracy_gates)
                  .map(([suite, status]) => `${suite} ${mark(status)}`)
                  .join(", ") || "—"}
              </td>
              <td data-label="Cost per answer">{usd(t.cost_per_answer_usd)}</td>
              <td data-label="Call latency p50 / p95">
                {sec(t.call_latency_p50_s)} / {sec(t.call_latency_p95_s)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table className="data">
        <caption className="sr-only">Cost and latency per answer</caption>
        <thead>
          <tr>
            <th scope="col">Answers</th>
            <th scope="col">Count</th>
            <th scope="col">Cost mean · p95</th>
            <th scope="col">Latency p50 · p95</th>
          </tr>
        </thead>
        <tbody>
          {data.answers.map((a) => (
            <tr key={a.type}>
              <td className="lead">{a.label}</td>
              <td data-label="Count">{a.answers ?? "—"}</td>
              <td data-label="Cost mean · p95">
                {usd(a.cost_mean_usd)} · {usd(a.cost_p95_usd)}
              </td>
              <td data-label="Latency p50 · p95">
                {sec(a.latency_p50_s)} · {sec(a.latency_p95_s)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
